+}
+
+::deep .thread-link {
+    background: none;
+    border: none;
+    color: #00a8fc;
+    font-size: 0.8rem;
+    cursor: pointer;
+    padding: 0.2rem 0;
+    margin-top: 0.2rem;
+}
+
+::deep .thread-link:hover {
+    text-decoration: underline;
+}
+
+::deep .message-actions {
+    position: absolute;
+    top: -8px;
+    right: 8px;
+    display: flex;
+    gap: 2px;
+    background: #2b2d31;
+    border: 1px solid #3f4147;
+    border-radius: 4px;
+    padding: 2px;
+}
+
+::deep .action-btn {
+    background: none;
+    border: none;
+    color: #b5bac1;
+    font-size: 0.75rem;
+    padding: 4px 8px;
+    cursor: pointer;
+    border-radius: 3px;
+}
+
+::deep .action-btn:hover {
+    background: #404249;
+    color: #f2f3f5;
+}
+
+::deep .emoji-picker {
+    position: absolute;
+    top: -8px;
+    right: 8px;
+    transform: translateY(-100%);
+    background: #2b2d31;
+    border: 1px solid #3f4147;
+    border-radius: 8px;
+    padding: 6px;
+    display: flex;
+    gap: 4px;
+}
+
+::deep .emoji-btn {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px;
+    border-radius: 4px;
+}
+
+::deep .emoji-btn:hover {
+    background: #404249;
+}
+
+/* Message input */
+::deep .message-input {
+    display: flex;
+    padding: 0.75rem 1rem;
+    gap: 0.5rem;
+    border-top: 1px solid #3f4147;
+    background: #313338;
+}
+
+::deep .message-input textarea {
+    flex: 1;
+    resize: none;
+    background: #383a40;
+    border: none;
+    border-radius: 8px;
+    padding: 0.6rem 1rem;
+    color: #dbdee1;
+    font-size: 0.9rem;
+    font-family: inherit;
+    outline: none;
+}
+
+::deep .message-input textarea:focus {
+    box-shadow: 0 0 0 1px #5865f2;
+}
+
+::deep .send-btn {
+    background: #5865f2;
+    color: white;
+    border: none;
+    border-radius: 8px;
+    padding: 0.6rem 1.2rem;
+    font-weight: 600;
+    cursor: pointer;
+    font-size: 0.85rem;
+}
+
+::deep .send-btn:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+::deep .send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread panel */
+::deep .thread-panel {
+    width: 25%;
+    min-width: 250px;
+    background: #2b2d31;
+    border-left: 1px solid #1e1f22;
+    display: flex;
+    flex-direction: column;
+    color: #dbdee1;
+}
+
+::deep .thread-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #3f4147;
+}
+
+::deep .thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #f2f3f5;
+}
+
+::deep .close-btn {
+    background: none;
+    border: none;
+    color: #b5bac1;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+::deep .close-btn:hover {
+    background: #404249;
+    color: #f2f3f5;
+}
+
+::deep .thread-root-message {
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #3f4147;
+    background: #232428;
+}
+
+::deep .thread-root-message p {
+    margin: 0.25rem 0 0;
+    font-size: 0.85rem;
+    color: #949ba4;
+}
+
+::deep .thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 0.75rem 1rem;
+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+}
+
+::deep .thread-reply {
+    padding: 0.4rem 0;
+}
+

